          "role": "dependency",
          "dependency_reason": "ZSTD_compress_insertDictionary handles the supplied bytes and calls ZSTD_loadDictionaryContent for raw content."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "The before-source block selector has distinct ordinary, external-dictionary, dictionary-match-state, and dedicated-dictionary-search compressors; ZSTD_buildSeqStore selects by match-state dictionary mode.",
